import 'package:cloud_firestore/cloud_firestore.dart';
class QuestionOption { const QuestionOption({required this.id,required this.text,required this.scores}); final String id,text; final Map<String,num> scores; factory QuestionOption.fromMap(Map<String,Object?> m)=>QuestionOption(id:m['id'] as String? ?? '',text:m['text'] as String? ?? '',scores:Map<String,num>.from(m['scores'] as Map? ?? {})); Map<String,Object?> toMap()=>{'id':id,'text':text,'scores':scores}; }
class QuestionModel { const QuestionModel({required this.id,required this.assessmentId,required this.text,required this.options,this.order=0}); final String id,assessmentId,text; final List<QuestionOption> options; final int order; factory QuestionModel.fromFirestore(DocumentSnapshot<Map<String,Object?>> d)=>QuestionModel(id:d.id,assessmentId:d['assessmentId'] as String,text:d['text'] as String,options:(d['options'] as List).map((e)=>QuestionOption.fromMap(Map<String,Object?>.from(e as Map))).toList(),order:d['order'] as int? ?? 0); Map<String,Object?> toFirestore()=>{'assessmentId':assessmentId,'text':text,'options':options.map((e)=>e.toMap()).toList(),'order':order}; }
